"""One-shot scaffold script for the X Quant X dashboard.

Run once from the repository root:  python scaffold_dashboard.py
Safe to re-run: every write is idempotent (skips if already applied).
"""
import base64
import os

NEW_FILES = {'src/investment_agent/dashboard/__init__.py': 'IiIiWCBRdWFudCBYIG1vbml0b3JpbmcgZGFzaGJvYXJkIHBhY2thZ2UuCgpNb25pdG9yaW5nLW9ubHk6IG5vIG1vZHVsZSBpbiB0aGlzIHBhY2thZ2UgaW1wb3J0cyB0aGUgQWxwYWNhIFRyYWRpbmdDbGllbnQKZGlyZWN0bHkgb3Igc3VibWl0cyBvcmRlcnMuIFNlZSBkYXRhX2xvYWRlci5weSBhbmQgbGF5b3V0LnB5IGRvY3N0cmluZ3MuCiIiIgo=', 'src/investment_agent/dashboard/colors.py': '', 'src/investment_agent/dashboard/data_loader.py': '', 'src/investment_agent/dashboard/charts.py': '', 'src/investment_agent/dashboard/layout.py': '', 'src/investment_agent/dashboard/app.py': '', 'run_dashboard.py': ''}
EXEC_SNIPPET = base64.b64decode('').decode("utf-8")
TEST_SNIPPET = base64.b64decode('').decode("utf-8")

def write_new_files():
    for rel_path, b64 in NEW_FILES.items():
        content = base64.b64decode(b64).decode("utf-8")
        os.makedirs(os.path.dirname(rel_path) or ".", exist_ok=True)
        with open(rel_path, "w", newline="\n") as f:
            f.write(content)
        print(f"wrote {rel_path}")

def append_execution_helpers():
    path = os.path.join("src", "investment_agent", "execution", "execution.py")
    with open(path, "r") as f:
        content = f.read()
    if "def get_positions():" in content:
        print(f"skip {path} (already has get_positions/get_order_history)")
        return
    marker = 'if __name__ == "__main__":'
    idx = content.index(marker)
    new_content = content[:idx] + EXEC_SNIPPET + "\n\n" + content[idx:]
    with open(path, "w", newline="\n") as f:
        f.write(new_content)
    print(f"updated {path} (added get_positions, get_order_history)")

def append_execution_tests():
    path = os.path.join("tests", "unit", "execution", "test_execution.py")
    with open(path, "r") as f:
        content = f.read()
    if "class TestGetPositions" in content:
        print(f"skip {path} (already has TestGetPositions/TestGetOrderHistory)")
        return
    marker = 'if __name__ == "__main__":'
    idx = content.index(marker)
    new_content = content[:idx] + TEST_SNIPPET + "\n\n" + content[idx:]
    with open(path, "w", newline="\n") as f:
        f.write(new_content)
    print(f"updated {path} (added TestGetPositions, TestGetOrderHistory)")

if __name__ == "__main__":
    write_new_files()
    append_execution_helpers()
    append_execution_tests()
    print()
    print("Done. Next steps:")
    print("  1. pip install dash plotly")
    print("  2. python -m pytest tests/ -v")
    print("  3. python run_dashboard.py   (then open http://127.0.0.1:8050)")
